<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../helpers/auth.php';require_once __DIR__.'/../helpers/redirect.php';require_once __DIR__.'/../helpers/validation.php';require_once __DIR__.'/../models/User.php';
class UserProfileController{public function index(){require_login();$db=Database::getConnection();$model=new User($db);$user=$model->find(current_user()['id']);$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$d=['nama'=>trim($_POST['nama']??''),'username'=>trim($_POST['username']??''),'email'=>trim($_POST['email']??''),'role_id'=>(int)$user['role_id'],'status'=>$user['status'],'password'=>$_POST['password']??''];if(!$d['nama']||!$d['username']||!filter_var($d['email'],FILTER_VALIDATE_EMAIL))$error='Nama, username, dan email wajib valid.';elseif($d['password']&&strlen($d['password'])<6)$error='Password baru minimal 6 karakter.';elseif($model->exists('username',$d['username'],$user['id']))$error='Username sudah digunakan.';elseif($model->exists('email',$d['email'],$user['id']))$error='Email sudah digunakan.';else{$model->update($user['id'],$d);login_user($model->find($user['id']));flash('success','Profile berhasil diperbarui.');redirect('profile');}}require __DIR__.'/../views/profile/index.php';}public function password(){require_login();$db=Database::getConnection();$model=new User($db);$user=$model->find(current_user()['id']);$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$old=$_POST['password_lama']??'';$new=$_POST['password_baru']??'';$confirm=$_POST['konfirmasi']??'';if(!password_verify($old,$user['password']))$error='Password lama salah.';elseif(strlen($new)<6)$error='Password baru minimal 6 karakter.';elseif($new!==$confirm)$error='Konfirmasi password tidak sama.';else{$model->update($user['id'],['nama'=>$user['nama'],'username'=>$user['username'],'email'=>$user['email'],'role_id'=>$user['role_id'],'status'=>$user['status'],'password'=>$new]);flash('success','Password berhasil diubah.');redirect('profile/password');}}require __DIR__.'/../views/profile/password.php';}}
